      fb.textContent = getBank().ltr ? (ok ? '✔ Correct' : '✘ Correct answer: ' + q.right) : (ok ? '✔ إجابة صحيحة' : '✘ الإجابة الصحيحة: ' + q.right);
      fb.style.color = ok ? '#86efac' : '#fca5a5';
